T["Noch keine Posts. Klick auf 'Neuer Schnappschuss' oder auf die Kamera in der Oasis-Leiste!"] = "Aucune publication pour l'instant. Cliquez sur 'Nouveau cliché' ou sur l'appareil photo dans la barre Oasis !"
T["Noch keine Punkte.\nSobald ein Offizier einen Raid startet, gibt es Einsatz-Punkte fuer alle, die dabei sind."] = "Pas encore de points.\nDès qu'un officier lance un raid, tous les participants gagnent des points d'engagement."
T["Noch keine Rezepte bekannt.\nOeffne deine Berufsfenster einmal - Oasis teilt sie dann automatisch mit der Gilde."] = "Pas encore de recettes connues.\nOuvre une fois tes fenêtres de métier - Oasis les partage ensuite automatiquement avec la guilde."
T["Noch keine Rezepte geteilt.\n\nSobald jemand mit Oasis sein Berufsfenster oeffnet, erscheinen die Rezepte hier. Wer welchen Beruf hat, siehst du schon jetzt:"] = "Aucune recette partagée.\n\nDès qu'un joueur avec Oasis ouvre sa fenêtre de métier, les recettes apparaissent ici. Qui a quel métier, tu peux déjà le voir :"
T["Noch keine Spiele."] = "Pas encore de parties."
T["Noch keine Umfragen."] = "Pas encore de sondages."
T["Noch keine bekannt - sobald jemand mit Oasis eine Quest fuer diesen Dungeon hat, steht sie hier."] = "Aucune connue pour l'instant - dès que quelqu'un avec Oasis a une quête pour ce donjon, elle apparaît ici."
T["Noch leer. Setz dich an ein Lagerfeuer und fuege\nden Buff in der Uebersicht ueber '+' zum Katalog hinzu."] = "Encore vide. Assieds-toi à un feu de camp et ajoute\nle buff dans la vue d'ensemble via « + » au catalogue."
T["Noch leer. Setz dich an ein Lagerfeuer und fuege\nden Buff rechts ueber '+' zum Katalog hinzu."] = "Encore vide. Assieds-toi à un feu de camp et ajoute\nle buff à droite via « + » au catalogue."
T["Noch nichts erledigt."] = "Rien d'accompli pour l'instant."
