T["Alle: Nie vor oder hinter Onyxia stehen (Atem/Schwanz).\nPhase 2 ab 65%: Feuerbaellen ausweichen, Welpen sofort umhauen.\nPhase 3 ab 40%: Furcht - Totem der Erdung und Furchtschutz bereit.\nTank: Onyxia mit dem Ruecken zur Wand, Kopf weg vom Raid.\nTank: Phase 3 sofort Aggro zurueckholen.\nHeiler: Tank hat Vorrang, in Phase 2 verteilt stehen.\nDD: Erst nach 3 Rueckenangriffen des Tanks voll loslegen.\nDD: Phase 2: Welpen vor Onyxia."] = "Tous : ne jamais se placer devant ou derrière Onyxia (souffle/queue).\nPhase 2 dès 65% : esquiver les boules de feu, tuer les dragonnets aussitôt.\nPhase 3 dès 40% : peur - totem de glèbe et gardien de peur prêts.\nTank : Onyxia dos au mur, tête loin du raid.\nTank : phase 3, reprendre l'aggro aussitôt.\nSoigneur : priorité au tank, se disperser en phase 2.\nDPS : à fond seulement après 3 Fracasser armure du tank.\nDPS : phase 2 : dragonnets avant Onyxia."
T["Alle: Schwarm-Ziel: rauslaufen.\nTank: Infernal-Tank abseits.\nHeiler: Schlaf entfernen, wo moeglich.\nDD: Infernals ignorieren, alles auf den Boss."] = "Tous : cible de l'essaim : sortir.\nTank : tank des infernaux à l'écart.\nSoigneur : dissiper le sommeil si possible.\nDPS : ignorer les infernaux, tout sur le boss."
T["Alle: Tod und Verfall sofort verlassen.\nTank: Mitte halten, bei Frostnova nicht bewegen.\nHeiler: Eisblock-Ziel schnell hochheilen.\nDD: Fernkampf weit verteilt (Eispfeil-Kette)."] = "Tous : quitter Mort et pourriture aussitôt.\nTank : tenir le centre, ne pas bouger pendant Nova de givre.\nSoigneur : soigner vite la cible du bloc de glace.\nDPS : distance bien dispersée (chaîne d'Éclair de givre)."
