T["Automatisch: Oasis legt alle 10 Minuten und beim Ausloggen einen Schnappschuss in den Gespeicherten Variablen ab (WTF/Account/<Konto>/SavedVariables/Oasis.lua). Das Programm Tools/oasis_export.py liest die Datei, macht JSON daraus und kann es an eure Weboberflaeche schicken. Addons haben keinen Internetzugriff - das ist der sichere Weg."] = "Automatique : toutes les 10 minutes et à la déconnexion, Oasis enregistre un instantané dans les variables sauvegardées (WTF/Account/<compte>/SavedVariables/Oasis.lua). Le programme Tools/oasis_export.py lit le fichier, le convertit en JSON et peut l'envoyer à votre page web. Les addons n'ont pas accès à Internet - c'est la voie sûre."
