T["Den Download findest du in unserem Discord."] = "Le téléchargement se trouve sur notre Discord."
T["Den Knopf kannst du auch direkt an der Minimap mit der Maus verschieben."] = "Tu peux aussi déplacer le bouton autour de la minicarte avec la souris."
T["Den Raid-Simulator gibt es nur in der Entwicklerversion."] = "Le simulateur de raid n'existe que dans la version de développement."
T["Den Raidplan bearbeiten duerfen Gildenleitung, Schlachtzugsleiter und Raid-Assistenten."] = "Seuls la direction, les chefs de raid et les assistants de raid peuvent modifier le plan de raid."
T["Den Talentbaum dieser Klasse kann WoW hier nicht anzeigen. Der Export-Text laesst sich unten kopieren."] = "WoW ne peut pas afficher ici l'arbre de talents de cette classe. Le texte d'export peut être copié ci-dessous."
T["Den ganzen Verlauf mit %s loeschen? Gemerkte Nachrichten gehen mit."] = "Supprimer tout l'historique avec %s ? Les messages mémorisés partent aussi."
T["Der Auftrag geht an alle Handwerker mit diesem Rezept - wer Zeit hat, nimmt ihn an."] = "La commande va à tous les artisans ayant cette recette - qui a le temps la prend."
T["Der Auftrag wird fuer alle zurueckgezogen."] = "La commande est retirée pour tout le monde."
T["Der Auftraggeber bekommt Bescheid, dass es fertig ist."] = "Le demandeur est prévenu que c'est prêt."
T["Der Auftraggeber bekommt Bescheid."] = "Le demandeur sera prévenu."
T["Der Basar ist leer"] = "Le bazar est vide"
T["Der Brachland-Chat mit seinen Spruechen"] = "Le chat des Tarides et ses répliques"
T["Der Client liefert gerade keine Fertigkeiten - nach dem Einloggen kurz warten."] = "Le client ne fournit pas de compétences pour l'instant - patiente un peu après la connexion."
T["Der Dungeonkompass: welcher Dungeon passt, was droppt dort fuer dich."] = "La boussole des donjons : quel donjon convient, ce qui y tombe pour toi."
T["Der Gegner stand nicht vor dir. Er stand hinter dir. Die ganze Zeit."] = "L'ennemi n'était pas devant toi. Il était derrière toi. Tout ce temps."
T["Der Gruppenanfuehrer kann dich zum Assistenten machen."] = "Le chef de groupe peut te nommer assistant."
T["Der Kampf war erst gesperrt und wurde nachtraeglich ausgewertet."] = "Le combat était d'abord verrouillé et a été analysé après coup."
T["Der Knopf laesst sich nicht mehr mit der Maus verschieben"] = "Le bouton ne peut plus être déplacé à la souris"
T["Der Link gilt fuer alle Leitungen."] = "Le lien vaut pour toute la direction."
T["Der Markt nutzt Preise aus dem AH-Addon Midas. Sobald du oder jemand aus der Gilde mit Midas im AH scannt, schaltet sich diese Seite frei."] = "Le marché utilise les prix de l'addon d'HV Midas. Dès que toi ou un membre de la guilde scannez l'hôtel des ventes avec Midas, cette page se débloque."
T["Der Mitschnitt der Spielzeiten ist aus. Schalte ihn ein, dann lernt Oasis mit jedem Abend dazu."] = "L'enregistrement des temps de jeu est désactivé. Active-le et Oasis en apprend un peu plus chaque soir."
T["Der Oasis-Rang ist der Gilden-Rang von Oasis - er steigt durch Zusammenspielen, Helfen, Handwerk, Termine und Abzeichen."] = "Le rang Oasis est le rang de guilde d'Oasis - il monte en jouant ensemble, en aidant, par l'artisanat, les événements et les badges."
T["Der Online-Sound dieser Person ist bei dir aus."] = "Le son de connexion de cette personne est coupé chez toi."
T["Der Rand des Oasis-Fensters leuchtet in deiner Farbe"] = "La bordure de la fenêtre Oasis brille de ta couleur"
T["Der Ring zeigt, wer ohne offene Punkte ist."] = "L'anneau montre qui n'a plus rien en attente."
T["Der Steinfresser"] = "Le Mange-pierre"
T["Der Termin liegt in der Vergangenheit."] = "L'événement est dans le passé."
T["Details"] = "Détails"
T["Di"] = "Mar"
T["Diagnose und Abgleich"] = "Diagnostic et synchronisation"
T["Diamant"] = "Diamant"
T["Diamant = Verbannen (Hexenmeister)"] = "Diamant = Bannir (Démoniste)"
T["Die Bank besucht. Mal kurz nachzaehlen."] = "Visite à la banque. Recompter vite fait."
T["Die Bannliste ist leer."] = "La liste des bannis est vide."
T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde /target eingegeben."] = "La saisie du chat a été touchée par Oasis (ex. bouton « Chuchoter »), puis /target a été saisi."
T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde dort ein /cast-Befehl eingegeben."] = "La saisie du chat a été touchée par Oasis (ex. bouton « Chuchoter »), puis une commande /cast y a été saisie."
T["Die Chat-Eingabe war von Oasis beruehrt, danach wurde /focus eingegeben."] = "La saisie du chat a été touchée par Oasis, puis /focus a été saisi."
T["Die Chat-Eingabe war von Oasis beruehrt, danach wurde ein Zauber-Befehl eingegeben."] = "La saisie du chat a été touchée par Oasis, puis une commande de sort a été saisie."
T["Die Dungeonkarten haben keine Koordinaten. Klick hier, dann auf die Stelle der Karte, an der du gerade stehst. An zwei weit entfernten Stellen gemacht, zeigt Oasis dich und deine Gruppe auf der Karte - fuer die ganze Gilde."] = "Les cartes de donjon n'ont pas de coordonnées. Clique ici, puis sur l'endroit de la carte où tu te trouves. Fait à deux endroits éloignés, Oasis te montre avec ton groupe sur la carte - pour toute la guilde."
T["Die Gilde bekommt Bescheid"] = "La guilde est prévenue"
T["Die Gilde sieht dabei, wem du antwortest. Standard: aus"] = "La guilde voit à qui tu réponds. Par défaut : désactivé"
T["Die Gilde sieht dein Feuer %d Minuten auf der Karte."] = "La guilde voit ton feu sur la carte pendant %d minutes."
T["Die Gilde sieht in der Chronik, was du erreicht hast"] = "La guilde voit dans la chronique ce que tu as accompli"
T["Die Gilde sucht gerade nichts aus diesem Dungeon."] = "La guilde ne cherche rien dans ce donjon pour l'instant."
T["Die Gilde vergibt noch keine Beute-Punkte - deine Werte erscheinen, sobald die Raidleitung einen Raid startet."] = "La guilde n'attribue pas encore de points de butin - tes valeurs apparaissent dès que la direction de raid lance un raid."
T["Die Gildenbank wurde noch nicht gelesen"] = "La banque de guilde n'a pas encore été lue"
T["Die Gildenleitung benennt Schlachtzugsleiter und Assistenz unter Krone > Module > Raids & Beute (Namen oder ab Gildenrang). Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "La direction de la guilde nomme chefs de raid et assistants sous Couronne > Modules > Raids & butin (par nom ou à partir d'un rang de guilde). Dans un raid en cours, le chef de raid et les assistants comptent aussi."
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "La direction de la guilde nomme les chefs de raid sous Couronne > Modules > Raids & butin. Dans un raid en cours, le chef de raid et les assistants comptent aussi."
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlt auch der Raidleiter."] = "La direction de la guilde nomme les chefs de raid sous Couronne > Modules > Raids & butin. Dans un raid en cours, le chef de raid compte aussi."
T["Die Gildenleitung erlaubt Gruppensuchen erst ab einem hoeheren Rang."] = "La direction de la guilde n'autorise les recherches de groupe qu'à partir d'un rang plus élevé."
T["Die Gildenleitung erlaubt Umfragen erst ab einem hoeheren Rang."] = "La direction de la guilde n'autorise les sondages qu'à partir d'un rang plus élevé."
T["Die Gildenleitung hat die Mitstreiter-Suche abgeschaltet."] = "La direction de la guilde a désactivé la recherche de partenaires."
T["Die Gildenleitung hat offene Einladungen abgeschaltet - fordere jemanden direkt heraus."] = "La direction de la guilde a désactivé les invitations ouvertes - défie quelqu'un directement."
T["Die Gildenleitung legt unter Krone > Module fest, welche Raenge das duerfen."] = "La direction de la guilde définit sous Couronne > Modules quels rangs y ont droit."
T["Die Gildensuche von WoW hilft beim Finden - neutral, ohne Werbung."] = "L'outil de recherche de guilde de WoW aide à trouver - neutre, sans publicité."
T["Die Grenze legt nur der Gildenmeister fest. Rang 1 = Gildenmeister."] = "Seul le maître de guilde fixe la limite. Rang 1 = maître de guilde."
T["Die Knoepfe schreiben den Befehl in die Chatzeile - erst mit Enter wird er ausgefuehrt."] = "Les boutons écrivent la commande dans la ligne de chat - elle ne s'exécute qu'avec Entrée."
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster (im Kampf nicht - dort gehoert Esc dem Spiel)."] = "Les raccourcis figurent aussi dans les raccourcis clavier de WoW sous AddOns > Oasis. Échap ferme la fenêtre Oasis (pas en combat - là, Échap appartient au jeu)."
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster, solange du zuletzt hineingeklickt hast."] = "Les raccourcis figurent aussi dans les raccourcis clavier de WoW sous AddOns > Oasis. Échap ferme la fenêtre Oasis tant que tu as cliqué dedans en dernier."
T["Die Leiste rollt nach oben weg; Maus an den oberen Rand und sie kommt herunter (nur wenn sie oben angedockt ist)"] = "La barre se replie vers le haut ; amène la souris au bord supérieur et elle redescend (seulement si elle est ancrée en haut)"
T["Die Reservierungs-Zeile erscheint nur, wenn du in einer Gruppe oder einem Schlachtzug bist"] = "La ligne de réservation n'apparaît que si tu es en groupe ou en raid"
T["Die Waechter der Sande"] = "La Balance des sables"
T["Die Weltkarte geoeffnet. Wo war nochmal Norden?"] = "Carte du monde ouverte. Où était le nord déjà ?"
T["Die echte Leiste oben zeigt jede Aenderung sofort"] = "La vraie barre en haut montre chaque changement aussitôt"
T["Die ersten 20 Ausdauer geben je 1, jeder weitere Punkt 10 Gesundheit."] = "Les 20 premiers points d'Endurance donnent 1 chacun, chaque point suivant 10 points de vie."
T["Die meisten Geisterlaeufe der Gilde. Der Friedhof hat eine Bank mit deinem Namen."] = "Le plus de courses de fantôme de la guilde. Le cimetière a un banc à ton nom."
T["Die meisten Screenshots der Gilde"] = "Le plus de captures d'écran de la guilde"
T["Die meisten Tode der letzten 7 Tage"] = "Le plus de morts sur les 7 derniers jours"
T["Die meisten vollen Taschen der Gilde"] = "Le plus de sacs pleins de la guilde"
