T["Niemand in der Gilde hat etwas mit diesem Namen."] = "Personne dans la guilde n'a d'objet de ce nom."
T["Niemand in der Gruppe kann ihn geben"] = "Personne dans le groupe ne peut le donner"
T["Niemand in diesem Filter - sehr gut!"] = "Personne dans ce filtre - très bien !"
T["Niemand ist so lange offline."] = "Personne n'est hors ligne depuis si longtemps."
T["Niemand sonst in der Gilde"] = "Personne d'autre dans la guilde"
T["Niemand steht kurz vor Respektvoll oder Ehrfuerchtig (ab 75 %)."] = "Personne n'est proche de Révéré ou Exalté (dès 75 %)."
T["Niemand. Stummschalten geht per Rechtsklick auf einen Namen im Gildenchat."] = "Personne. Rends quelqu'un muet par clic droit sur un nom dans le canal de guilde."
T["Ninja-Markierung entfernen"] = "Retirer la marque ninja"
T["Noch aus"] = "Encore désactivé"
T["Noch gesperrt"] = "Encore verrouillé"
T["Noch hat niemand Material beigetragen."] = "Personne n'a encore fourni de composants."
T["Noch kein Highlight - die Woche ist jung."] = "Pas encore de temps fort - la semaine est jeune."
T["Noch kein Kampf ausgewertet"] = "Aucun combat analysé"
T["Noch kein Muster - dafuer braucht es mehrere Versuche."] = "Pas encore de motif - il faut plusieurs essais."
T["Noch kein Ready-Check"] = "Pas encore d'appel"
T["Noch kein Ready-Check gelaufen."] = "Aucun appel effectué."
T["Noch kein Scan - sobald jemand mit Midas scannt, stehen hier Schnaeppchen."] = "Pas encore de scan - dès que quelqu'un scanne avec Midas, les bonnes affaires apparaissent ici."
T["Noch kein Termin - melde dein Interesse, dann weiss die Raidleitung, wann es passt."] = "Pas encore d'événement - signale ton intérêt pour que la direction de raid sache quand ça convient."
T["Noch kein Tod - weiter so!"] = "Pas encore de mort - continue !"
T["Noch kein Tod eines seltenen Gegners erfasst."] = "Aucune mort d'ennemi rare enregistrée."
T["Noch keine Abklingzeiten geteilt - wer Transmutation, Mondstoff oder einen Salzstreuer hat, erscheint hier."] = "Aucun temps de recharge partagé - ceux qui ont Transmutation, Étoffe lunaire ou une Salière apparaissent ici."
T["Noch keine Abzeichen"] = "Pas encore de badges"
T["Noch keine Ausruestung bekannt - Spieler in der Naehe anvisieren und betrachten (Oasis betrachtet Mitspieler in der Gruppe automatisch)."] = "Équipement inconnu - cible et inspecte les joueurs proches (Oasis inspecte automatiquement les membres du groupe)."
T["Noch keine Berufe gelernt."] = "Aucun métier appris."
T["Noch keine Beute aus diesem Dungeon im Gilden-Log."] = "Pas encore de butin de ce donjon dans le journal de guilde."
T["Noch keine Beute erfasst"] = "Aucun butin enregistré"
T["Noch keine Bewerber. Name oben eintragen - Klick auf den Status schaltet weiter."] = "Pas encore de candidats. Saisis un nom en haut - clic sur le statut pour le faire avancer."
T["Noch keine Daten - Ausruestung kommt mit dem naechsten Abgleich der Oasis-Nutzer."] = "Pas encore de données - l'équipement arrive avec la prochaine synchro Oasis."
T["Noch keine Daten - Mitglieder schicken ihre Messung alle 15 Min (ab dieser Version)."] = "Pas encore de données - les membres envoient leur mesure toutes les 15 min (depuis cette version)."
T["Noch keine Daten - oeffne einmal das Sammlungsfenster oder trage Reittiere und Haustiere in der Tasche. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "Pas encore de données - ouvre une fois la fenêtre des collections ou porte montures et mascottes dans tes sacs. Les membres avec Oasis apparaissent ici une fois en ligne."
T["Noch keine Daten von der Gilde."] = "Pas encore de données de la guilde."
T["Noch keine Daten. Sobald Gildenmitglieder mit Oasis einloggen, erscheinen ihre Raid-IDs hier."] = "Pas encore de données. Dès que des membres se connectent avec Oasis, leurs verrouillages de raid apparaissent ici."
T["Noch keine Dungeon-Laeufe aufgezeichnet."] = "Aucune sortie en donjon enregistrée."
T["Noch keine Dungeons geplant."] = "Aucun donjon prévu."
T["Noch keine Eintraege."] = "Aucune entrée."
T["Noch keine Emojis benutzt - Favoriten aus der Emoji-Auswahl erscheinen hier."] = "Aucun emoji utilisé - les favoris du sélecteur d'emojis apparaissent ici."
T["Noch keine Favoriten - Diamant anklicken."] = "Pas encore de favoris - clique sur le losange."
T["Noch keine Favoriten - Stern oder Rechtsklick auf einen Sound."] = "Pas encore de favoris - étoile ou clic droit sur un son."
T["Noch keine Favoriten.\nRechtsklick auf ein Emoji merkt es hier."] = "Pas encore de favoris.\nClic droit sur un emoji pour le mémoriser ici."
T["Noch keine Fluesternachrichten."] = "Aucun chuchotement."
T["Noch keine Fluesternachrichten. Schreib jemandem aus der Gilde!"] = "Aucun chuchotement. Écris à quelqu'un de la guilde !"
T["Noch keine Fraktionen entdeckt."] = "Aucune faction découverte."
T["Noch keine Gildenziele. Lege das erste an - z. B. eine legendaere Waffe oder Material fuer den Raid."] = "Pas encore d'objectifs de guilde. Crée le premier - ex. une arme légendaire ou des composants pour le raid."
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch - mit Zeitstrahl der Tode und wiederkehrenden Mustern."] = "Pas encore de rapports de combat. Après le premier boss, chaque essai apparaît ici - avec chronologie des morts et motifs récurrents."
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch."] = "Pas encore de rapports de combat. Après le premier boss, chaque essai apparaît ici."
T["Noch keine Kandidaten. Spiel mit Leuten ausserhalb der Gilde - wer ohne Gilde ist und gut bewertet wird, landet hier."] = "Pas encore de candidats. Joue avec des gens hors guilde - ceux sans guilde et bien notés arrivent ici."
T["Noch keine Kombos.\nShift+Klick auf mehrere Emojis, dann Merken."] = "Pas encore de combos.\nMaj+clic sur plusieurs emojis, puis Mémoriser."
T["Noch keine Kontakte. Geh mit anderen Oasis-Nutzern in eine Gruppe - Oasis merkt sie sich dann hier, auch ohne Gilde."] = "Pas encore de contacts. Groupe-toi avec d'autres utilisateurs d'Oasis - Oasis les mémorise ici, même sans guilde."
T["Noch keine Meilensteine. Level auf, lern Berufe - hier entsteht deine Geschichte."] = "Pas encore d'étapes. Monte de niveau, apprends des métiers - ton histoire commence ici."
T["Noch keine Meldungen aus der Gilde."] = "Pas encore de signalements de la guilde."
T["Noch keine Momente - spiel einfach, Oasis schreibt mit."] = "Pas encore de moments - joue simplement, Oasis prend note."
T["Noch keine Nachrichten im Offizierschat. Alles, was ab jetzt im Kanal /o geschrieben wird, steht hier."] = "Pas encore de messages dans le canal officiers. Tout ce qui est écrit dans /o à partir de maintenant apparaît ici."
T["Noch keine Positionen - die Karte fuellt sich, sobald Mitglieder mit Oasis unterwegs sind."] = "Pas encore de positions - la carte se remplit dès que des membres avec Oasis sont en route."
T["Noch keine Preise. Sobald jemand mit Midas im AH scannt, stehen sie hier."] = "Pas encore de prix. Dès que quelqu'un scanne l'HV avec Midas, ils apparaissent ici."
T["Noch keine Profile gespeichert."] = "Aucun profil enregistré."
T["Noch keine Punkte"] = "Pas encore de points"
T["Noch keine Raidtage erfasst. Der Raidleiter (mit Oasis) schreibt sie bei jedem Boss-Kill automatisch mit."] = "Aucun jour de raid enregistré. Le chef de raid (avec Oasis) les enregistre automatiquement à chaque boss tué."
T["Noch keine Regeln"] = "Pas encore de règles"
T["Noch keine Regeln. Nimm eine Schnell-Vorlage oder leg oben eine eigene an."] = "Pas encore de règles. Prends un modèle rapide ou crée la tienne en haut."
T["Noch keine Rufdaten. Sie kommen automatisch, sobald Mitglieder mit Oasis online sind."] = "Pas encore de données de réputation. Elles arrivent automatiquement dès que des membres avec Oasis sont en ligne."
T["Noch keine Sammlung geteilt. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "Aucune collection partagée. Elles apparaissent ici dès que des membres avec Oasis sont en ligne."
T["Noch keine Sets."] = "Pas encore d'ensembles."
T["Noch keine Sichtung. Sobald jemand mit Oasis einen seltenen Gegner sieht, steht er hier."] = "Aucune observation. Dès que quelqu'un avec Oasis voit un ennemi rare, il apparaît ici."
T["Noch keine Spielzeiten bekannt. Oasis lernt mit jedem Abend, an dem du online bist - und uebernimmt die Profile der anderen."] = "Aucun horaire de jeu connu. Oasis apprend chaque soir où tu es en ligne - et reprend les profils des autres."
T["Noch keine Suche. Level eingeben und \"Suchen\" klicken - Spieler mit Gilde werden ausgeblendet."] = "Pas encore de recherche. Saisis les niveaux et clique sur \"Rechercher\" - les joueurs avec guilde sont masqués."
T["Noch keine Taktiken."] = "Pas encore de tactiques."
T["Noch keine Taktiken. Die Raidleitung kann je Boss eine kurze Taktik anlegen - alle sehen sie hier und bekommen sie beim Anvisieren angezeigt."] = "Pas encore de tactiques. La direction de raid peut créer une courte tactique par boss - tous la voient ici et en ciblant le boss."
T["Noch keine Talente bekannt. Mitglieder mit Oasis teilen sie automatisch; andere Spieler: anvisieren und betrachten (Rechtsklick > Betrachten) oder hier mit Ziel erneut oeffnen."] = "Talents inconnus. Les membres avec Oasis les partagent automatiquement ; autres joueurs : cible et inspecte (clic droit > Inspecter) ou rouvre ici avec une cible."
T["Noch keine Vergaben - sie erscheinen hier, sobald die Raidleitung Beute verteilt."] = "Pas encore d'attributions - elles apparaissent dès que la direction de raid distribue le butin."
T["Noch keine Werte - nach dem naechsten Kampf erscheint hier, wer vorne liegt."] = "Pas encore de valeurs - après le prochain combat, tu verras ici qui mène."
T["Noch keine Wunschtage - tippe an, wann du kannst."] = "Pas encore de jours souhaités - indique quand tu peux."
T["Noch keine Wunschtage gemeldet."] = "Aucun jour souhaité signalé."
T["Noch keine Ziele. Leg oben eins an - Oasis hakt es automatisch ab."] = "Pas encore d'objectifs. Crée-en un en haut - Oasis le coche automatiquement."
T["Noch keine Zusagen - sei der Erste!"] = "Pas encore d'inscriptions - sois le premier !"
T["Noch keine eigene Beute"] = "Pas encore de butin perso"
T["Noch keine eigene Beute erfasst (ab Qualitaet 'Selten', einstellbar)."] = "Aucun butin perso enregistré (dès qualité 'Rare', réglable)."
T["Noch nicht angemeldet - waehle unten deine Rolle"] = "Pas encore inscrit - choisis ton rôle ci-dessous"
T["Noch nicht bereit"] = "Pas encore prêt"
T["Noch nicht fuer die Gilde uebernommen:"] = "Pas encore appliqué à la guilde :"
T["Noch nicht kalibriert - Kalibrieren?"] = "Pas encore calibré - calibrer ?"
T["Noch nichts auf der Wunschliste.\nTrag oben ein, was du brauchst - alle mit Oasis sehen es im Tooltip und beim Looten."] = "Rien sur la liste de souhaits.\nAjoute en haut ce dont tu as besoin - tous ceux avec Oasis le voient dans l'infobulle et au butin."
T["Noch nichts aufgezeichnet."] = "Rien d'enregistré."
T["Noch nichts benutzt."] = "Rien d'utilisé."
T["Noch nichts blockiert. Sobald WoW Oasis blockiert, steht hier welche Funktion und was Oasis kurz vorher gemacht hat."] = "Rien de bloqué. Dès que WoW bloque Oasis, tu vois ici quelle fonction et ce qu'Oasis faisait juste avant."
T["Noch nichts eingelesen"] = "Rien d'importé"
T["Noch nichts geangelt."] = "Rien pêché."
T["Noch nichts gemerkt - Rechtsklick auf eine Nachricht: Nachricht merken."] = "Rien de mémorisé - clic droit sur un message : Mémoriser le message."
T["Noch nichts passiert - zieht los und schreibt Geschichte!"] = "Il ne s'est rien passé - partez écrire l'histoire !"
T["Noch nichts reserviert"] = "Rien de réservé"
T["Noch nichts reserviert - ein Item pro Termin."] = "Rien de réservé - un objet par date."
T["Noch nichts reserviert."] = "Rien de réservé."
T["Noch nichts verkauft."] = "Rien de vendu."
T["Noch nichts verteilt. Sobald eine Regel greift, steht es hier."] = "Rien distribué. Dès qu'une règle s'applique, ça apparaît ici."
T["Noch nie direkt mit dir abgeglichen"] = "Jamais synchronisé directement avec toi"
T["Noch niemand angefluestert."] = "Tu n'as encore chuchoté à personne."
T["Noch niemand aus der Gilde hat es uebrig."] = "Personne dans la guilde n'en a en trop."
T["Noch niemand aus der Gilde mit deiner Spezialisierung teilt seine Talente (Oasis-Nutzer teilen automatisch)."] = "Personne dans la guilde avec ta spécialisation ne partage encore ses talents (les utilisateurs d'Oasis partagent automatiquement)."
T["Noch niemand gegangen, seit Oasis mitschreibt."] = "Personne n'est parti depuis qu'Oasis enregistre."
T["Noch niemand gemeldet - sei der Erste!"] = "Personne d'inscrit - sois le premier !"
T["Noch niemand sonst kennt das Rezept."] = "Personne d'autre ne connaît la recette."
T["Noch niemand teilt seine Handelsbilanz."] = "Personne ne partage encore son bilan commercial."
T["Noch niemand teilt seine Handelsbilanz. Unten 'Bilanz teilen' einschalten - dann geht's los."] = "Personne ne partage encore son bilan commercial. Active 'Partager le bilan' ci-dessous pour commencer."
T["Noch teilt niemand mit Oasis handelbare Teile. Je mehr Mitglieder Oasis nutzen, desto voller wird es hier."] = "Personne ne partage encore d'objets échangeables via Oasis. Plus il y a de membres avec Oasis, plus ça se remplit."
T["Noch zu uebergeben"] = "Encore à remettre"
T["Noch zu wenig Daten fuer eine Stosszeit"] = "Pas assez de données pour une heure de pointe"
T["Normal"] = "Normal"
T["Normal meldet Oasis nur Suchen, die du selbst noch offen hast"] = "Normalement, Oasis signale seulement les recherches que tu as toi-même encore ouvertes"
T["Notiz (Klasse, Kontakt, Eindruck ...)"] = "Note (classe, contact, impression ...)"
T["Notiz an den Plundermeister (optional)"] = "Note au maître du butin (facultatif)"
T["Notiz der Gildenleitung"] = "Note de la direction de guilde"
T["Notiz von %s: %s"] = "Note de %s : %s"
T["Notiz zu %s"] = "Note sur %s"
T["Notiz zur Person"] = "Note sur la personne"
T["Notiz zur Suche (Zeit, Treffpunkt) ..."] = "Note pour la recherche (heure, lieu de rendez-vous) ..."
T["Notizen sehen und schreiben nur Offiziere."] = "Seuls les officiers voient et écrivent les notes."
T["Nur %s"] = "Seulement %s"
T["Nur Abende vorschlagen"] = "Ne proposer que les soirées"
T["Nur Banner und drei Spalten (wer ist online, was passiert, als Naechstes) - ohne Kacheln und Highlight-Zeile"] = "Seulement la bannière et trois colonnes (qui est en ligne, ce qui se passe, à venir) - sans tuiles ni ligne phare"
T["Nur Dungeons, deren Beute besser ist als deine angelegte Ausruestung."] = "Seulement les donjons dont le butin surpasse votre équipement porté."
T["Nur Eintraege dieser Person"] = "Seulement les entrées de cette personne"
T["Nur Farbverlauf"] = "Dégradé seulement"
T["Nur Gegner im Kampf"] = "Seulement les ennemis en combat"
T["Nur Gildenleitung"] = "Direction de guilde seulement"
T["Nur Gruppenquests beruecksichtigen"] = "Quêtes de groupe seulement"
T["Nur Lagerfeuer in meinem Gebiet melden"] = "Signaler seulement les feux de camp dans ma zone"
T["Nur Mains ab Level"] = "Seulement les persos principaux dès le niveau"
T["Nur Mitglieder bis zu diesem Rang duerfen eine Gruppensuche starten (10 = alle)."] = "Seuls les membres jusqu'à ce rang peuvent lancer une recherche de groupe (10 = tous)."
T["Nur Mitglieder bis zu diesem Rang duerfen eine neue Umfrage starten (10 = alle)."] = "Seuls les membres jusqu'à ce rang peuvent lancer un nouveau sondage (10 = tous)."
T["Nur Mitglieder mit Oasis. Geteilt werden offene Questitems, uebrige Questitems und teilbare Quests."] = "Seulement les membres avec Oasis. Partagés : objets de quête manquants, objets de quête en trop et quêtes partageables."
T["Nur Oasis-Spieler"] = "Joueurs Oasis seulement"
T["Nur Oasis-Spieler: jeder sieht sie in seiner eigenen Sprache."] = "Joueurs Oasis seulement : chacun le voit dans sa propre langue."
T["Nur Offiziere und Gildenleitung sehen diesen Kanal (/o)."] = "Seuls les officiers et la direction de guilde voient ce canal (/o)."
T["Nur Plundermeister, Anfuehrer oder Assistenten koennen verteilen."] = "Seuls le maître du butin, le chef ou les assistants peuvent distribuer."
T["Nur Rezepte, die du selbst kannst"] = "Seulement les recettes que vous connaissez"
T["Nur Rezepte, die gerade jemand online herstellen kann"] = "Seulement les recettes qu'un joueur en ligne peut fabriquer"
T["Nur Upgrades"] = "Améliorations seulement"
T["Nur an die eigene Gruppe, fuer die Dungeon-Karte"] = "Seulement à votre groupe, pour la carte du donjon"
T["Nur ansehen - bearbeiten: Leitung, Schlachtzugsleiter, Raid-Assistenten"] = "Lecture seule - édition : direction, chefs de raid, assistants de raid"
T["Nur ansehen - zeichnen darf der Raidleiter"] = "Lecture seule - le chef de raid dessine"
T["Nur auf diesem PC"] = "Seulement sur ce PC"
T["Nur ausgeblendet - klick hier, um zurueckzukehren."] = "Seulement masqué - cliquez ici pour revenir."
T["Nur bei dir"] = "Seulement chez vous"
T["Nur bei dir gespeichert"] = "Enregistré seulement chez vous"
T["Nur bei gleicher Klasse und Spezialisierung."] = "Seulement avec la même classe et spécialisation."
T["Nur das Noetigste"] = "Le strict nécessaire"
T["Nur der Gildenmeister kann das aendern."] = "Seul le maître de guilde peut modifier cela."
T["Nur der Gildenmeister, hoechstens 10 Raenge."] = "Seul le maître de guilde, 10 rangs au plus."
T["Nur der Gruppenleiter kann eine Suche starten."] = "Seul le chef de groupe peut lancer une recherche."
T["Nur der Gruppenleiter kann suchen"] = "Seul le chef de groupe peut chercher"
T["Nur die Gildenleitung kann das aendern."] = "Seule la direction de guilde peut modifier cela."
T["Nur die Gildenleitung kann die Deathroll-Rangliste zuruecksetzen."] = "Seule la direction de guilde peut réinitialiser le classement Deathroll."
T["Nur die wichtigsten Bereiche sind an."] = "Seules les sections principales sont activées."
T["Nur diese Person hoert ihn (wenn sie Oasis hat)."] = "Seule cette personne l'entend (si elle a Oasis)."
T["Nur diesen Abschnitt posten"] = "Publier seulement cette section"
T["Nur fehlende"] = "Manquants seulement"
T["Nur fuer Anfuehrer und Assistenten"] = "Chef et assistants seulement"
T["Nur fuer Offiziere"] = "Officiers seulement"
T["Nur fuer Schlachtzugsleiter"] = "Chefs de raid seulement"
T["Nur fuer Schlachtzugsleiter & Assistenz"] = "Chefs de raid & assistants seulement"
T["Nur fuer Umfragen, die du gestartet oder bei denen du abgestimmt hast"] = "Seulement pour les sondages que vous avez lancés ou votés"
T["Nur fuer den Schlachtzugsleiter"] = "Chef de raid seulement"
T["Nur fuer dich sichtbar - steht im Kopf des Gespraechs mit %s."] = "Visible seulement par vous - en tête de la conversation avec %s."
T["Nur fuer dich: nach dem Kampf eine Zeile mit Dauer und erstem Tod"] = "Pour vous seul : une ligne avec durée et première mort après le combat"
T["Nur fuer die Fehlersuche. Standard: aus"] = "Seulement pour le débogage. Par défaut : désactivé"
T["Nur fuer die Gildenleitung"] = "Direction de guilde seulement"
T["Nur fuers Aussehen"] = "Juste pour l'apparence"
T["Nur guenstig"] = "Bon marché seulement"
T["Nur handelbare (nicht seelengebundene) Teile. Werte nach Klasse und Rolle wie beim Verbesserungs-Pfeil; Bank zaehlt erst nach einmal Oeffnen."] = "Objets échangeables (non liés) seulement. Évalués par classe et rôle comme la flèche d'amélioration ; la banque compte après une première ouverture."
T["Nur in der offenen Welt; kann viele Eintraege erzeugen"] = "Monde ouvert seulement ; peut créer beaucoup d'entrées"
T["Nur in einer Gruppe und mit der Quest im Log."] = "Seulement en groupe et avec la quête dans le journal."
T["Nur in einer Gruppe."] = "Seulement en groupe."
T["Nur mein Gebiet"] = "Seulement ma zone"
T["Nur meine"] = "Seulement les miens"
T["Nur mit Helfern"] = "Seulement avec aides"
T["Nur mit Upgrades"] = "Seulement avec améliorations"
T["Nur neue"] = "Nouveaux seulement"
T["Nur offene Challenges, die zu deinen Charakteren passen (Klassen, Berufe) - plus alle Dungeons, Raids, PvP und Abenteuer."] = "Seulement les défis ouverts adaptés à vos personnages (classes, métiers) - plus tous les donjons, raids, JcJ et aventures."
T["Nur ohne Belohnungs-Auswahl und ohne Kosten. Shift = aussetzen."] = "Seulement sans choix de récompense ni coût. Maj = ignorer."
T["Nur online"] = "En ligne seulement"
T["Nur von Leitern, bei denen du ueber Oasis angefragt hast"] = "Seulement des chefs sollicités via Oasis"
T["Nur von Oasis-Nutzern"] = "Seulement des utilisateurs d'Oasis"
T["Nur von Oasis-Nutzern, 30 Tage"] = "Seulement des utilisateurs d'Oasis, 30 jours"
T["Nur wenn online"] = "Seulement si en ligne"
T["OFFEN"] = "OUVERT"
T["OK"] = "OK"
T["Oasigram-Beitraege"] = "Publications Oasigram"
T["Oasis %s ist da"] = "Oasis %s est disponible"
T["Oasis %s%s ist da - du hast noch %s. Bitte im Discord herunterladen."] = "Oasis %s%s est disponible - vous avez encore %s. Téléchargez-le sur Discord."
T["Oasis antwortet automatisch auf pc / preis mit Item-Link im Gildenchat"] = "Oasis répond automatiquement à pc / prix avec un lien d'objet dans le canal de guilde"
T["Oasis begleitet %s ab heute (Stufe %d)"] = "Oasis accompagne %s dès aujourd'hui (niveau %d)"
T["Oasis beim Einloggen oeffnen"] = "Ouvrir Oasis à la connexion"
T["Oasis bekannt machen"] = "Faire connaître Oasis"
T["Oasis belegt gerade %s (Kern + geladene Module)."] = "Oasis occupe actuellement %s (noyau + modules chargés)."
T["Oasis belegt gerade %s."] = "Oasis occupe actuellement %s."
T["Oasis fasst deine Charaktere in der Gilde zu einem Spieler zusammen. Spaeter aenderbar unter Einstellungen > Profil & Sichern."] = "Oasis regroupe vos personnages de la guilde en un seul joueur. Modifiable plus tard dans Paramètres > Profil & sauvegarde."
T["Oasis funktioniert trotzdem fuer dich: dein Profil, Ziele, Dungeons und Sammlungen sind da."] = "Oasis fonctionne quand même pour vous : votre profil, objectifs, donjons et collections sont là."
T["Oasis hatte Blizzard-Knoepfe (Aktionsleisten, Taschen, Tooltip, Chat) beruehrt (ab 0.5.504 behoben - bitte Oasis aktualisieren)."] = "Oasis touchait des boutons Blizzard (barres d'action, sacs, infobulle, discussion) (corrigé dès 0.5.504 - mettez Oasis à jour)."
T["Oasis ist bereit"] = "Oasis est prêt"
T["Oasis kann sehr viel. Waehle, was du nutzen willst - der Rest bleibt erstmal aus und laesst sich jederzeit unter 'Entdecken' einschalten."] = "Oasis fait beaucoup. Choisissez ce que vous voulez utiliser - le reste reste désactivé et peut être activé à tout moment dans 'Découvrir'."
T["Oasis liest nach jedem Kampf Blizzards eingebaute Schadensanzeige - auch in Instanzen."] = "Oasis lit après chaque combat le compteur de dégâts intégré de Blizzard - aussi en instance."
T["Oasis liest nach jedem Kampf Blizzards eingebaute Schadensanzeige - das Kampflog ist in WoW Forever fuer Addons gesperrt. Mitspieler brauchen Oasis ab 0.5.577. Werte, die Blizzard verschluesselt (z.B. in Instanzen), zaehlen nicht."] = "Oasis lit après chaque combat le compteur de dégâts intégré de Blizzard - le journal de combat est bloqué pour les addons dans WoW Forever. Les autres joueurs ont besoin d'Oasis 0.5.577+. Les valeurs chiffrées par Blizzard (ex. en instance) ne comptent pas."
T["Oasis oeffnen / schliessen"] = "Ouvrir / fermer Oasis"
T["Oasis ohne Gilde"] = "Oasis sans guilde"
T["Oasis tauscht Daten nur mit Gildenmitgliedern, die Oasis auch haben. Im Kampf und in Instanzen pausiert der Austausch."] = "Oasis n'échange des données qu'avec les membres de guilde ayant aussi Oasis. L'échange est suspendu en combat et en instance."
