T["Wer"] = "Qui"
T["Wer Daten schickt, die bei anderen abgelehnt werden (keine Rechte, gefaelschter Urheber, ausgedachte Eintraege). Ein unveraendertes Oasis tut das praktisch nie - ein Hinweis, kein Beweis."] = "Ceux qui envoient des données refusées chez les autres (pas de droits, auteur falsifié, entrées inventées). Un Oasis non modifié ne le fait quasiment jamais - un indice, pas une preuve."
T["Wer Interesse meldet, erscheint hier auf einem passenden Platz. Steht ein Termin, meldest du dich direkt auf der Karte an."] = "Ceux qui signalent leur intérêt apparaissent ici sur un créneau adapté. Une fois l'événement fixé, inscrivez-vous directement sur sa carte."
T["Wer aus der Gilde das Item auf der Wunschliste hat"] = "Qui dans la guilde a l'objet sur sa liste de souhaits"
T["Wer den Bereich in der Navigation sieht (die Gildenleitung sieht immer alles)"] = "Qui voit cette section dans la navigation (la direction voit toujours tout)"
T["Wer die Gilde verlassen hat oder entfernt wurde. Kommt jemand zurueck, meldet Oasis das der Gildenleitung."] = "Ceux qui ont quitté la guilde ou ont été renvoyés. Si quelqu'un revient, Oasis le signale à la direction."
T["Wer die Krone oben sieht. Ohne Rechte ist sie grau und oeffnet nur eine Vorschau."] = "Qui voit la couronne en haut. Sans droits, elle est grise et n'ouvre qu'un aperçu."
T["Wer eine Nachricht oben im Gildenchat anpinnen darf"] = "Qui peut épingler un message en haut du canal de guilde"
T["Wer einladen darf, ist noch nicht bekannt - logge einmal mit deinem Main ein, dann merkt sich Oasis die Gildenleitung."] = "On ne sait pas encore qui peut inviter - connectez-vous une fois avec votre principal et Oasis retiendra la direction de la guilde."
T["Wer geht mit nach %s? Ich suche %s"] = "Qui vient à %s ? Je cherche %s"
T["Wer hat ...?"] = "Qui a ... ?"
T["Wer hat das Questitem, das du brauchst? Und wem kannst du helfen?"] = "Qui a l'objet de quête dont vous avez besoin ? Et qui pouvez-vous aider ?"
T["Wer hat was bekommen"] = "Qui a reçu quoi"
T["Wer im Raid Punkte (Einsatz/Beute) buchen darf."] = "Qui peut attribuer des points (présence/butin) en raid."
T["Wer in Gruppe oder Raid welche Buffs hat - und was noch fehlt"] = "Qui a quels buffs dans le groupe ou le raid - et ce qui manque"
T["Wer ist bereit? Ampeln je Spieler"] = "Qui est prêt ? Voyants par joueur"
T["Wer ist diese Woche schon gebunden, wer ist frei und freigeschaltet - Mains und Twinks"] = "Qui est déjà verrouillé cette semaine, qui est libre et harmonisé - principaux et rerolls"
T["Wer ist online"] = "Qui est en ligne"
T["Wer ist online?"] = "Qui est en ligne ?"
T["Wer ist wann online"] = "Qui est en ligne quand"
T["Wer ist wie weit"] = "Qui en est où"
T["Wer kann was herstellen, Markt, Gildenbank"] = "Qui fabrique quoi, marché, banque de guilde"
T["Wer koennte mit: %s"] = "Qui pourrait venir : %s"
T["Wer koennte mit?"] = "Qui pourrait venir ?"
T["Wer oft dabei ist und wenig bekommen hat, ist bei 'Bedarf' zuerst dran. Jede Woche verfaellt ein Teil der Punkte."] = "Ceux souvent présents qui ont peu reçu passent en premier en 'Besoin'. Une partie des points décroît chaque semaine."
T["Wer sich mit passender Rolle meldet, wird sofort in deine Gruppe eingeladen."] = "Ceux qui s'inscrivent avec un rôle adapté sont invités immédiatement dans votre groupe."
T["Wer steht wo bei welcher Fraktion? Kurz vor dem Ziel, gemeinsam farmen, Fortschritt dieser Woche"] = "Qui en est où avec quelle faction ? Proche du but, farmer ensemble, progression de la semaine"
T["Wer teilt am meisten aus, heilt am meisten, steckt am meisten ein?"] = "Qui inflige le plus, soigne le plus, encaisse le plus ?"
T["Wer zur Gildenleitung gehoert, legt der Gildenmeister unter Krone > Gilde fest."] = "Le maître de guilde définit qui fait partie de la direction sous Couronne > Guilde."
T["Werbung"] = "Recrutement"
T["Werte"] = "Stats"
T["Werte bringen deiner Rolle nichts"] = "stats inutiles pour votre rôle"
T["Werte nur zur Info"] = "stats à titre indicatif"
T["Werte, Jahrbuch, Tagesziel, Rekorde und Abenteuer deines Charakters."] = "Stats, annuaire, objectif du jour, records et aventures de votre personnage."
T["Werte: +Heilung, Intelligenz, Willenskraft, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung;Heilen: Verjuengung und Nachwachsen vorab, Heilende Beruehrung fuer grosse Treffer;Tipp: Anregen fuer Mana, Wiedergeburt fuer gefallene Heiler"] = "Stats : +soins, intelligence, esprit, régén. mana;Arme : bâton ou arme à une main + main gauche avec soins;Soins : Récupération et Rétablissement en avance, Toucher guérisseur pour les gros coups;Astuce : Innervation pour le mana, Renaissance pour les soigneurs tombés"
T["Werte: +Heilung, Intelligenz, Zauber-Krit (Erleuchtung gibt Mana zurueck), Mana-Reg.;Waffe: Einhandwaffe + Nebenhand/Schild mit Heilung;Heilen: Lichtblitz fuer kleinen Schaden, Heiliges Licht (niedriger Rang) fuer grosse Treffer;Tipp: Segen verteilen, Gottesschutz wenn du gezogen wirst"] = "Stats : +soins, intelligence, critique des sorts (Illumination rend du mana), régén. mana;Arme : arme à une main + main gauche/bouclier avec soins;Soins : Éclair lumineux pour les petits dégâts, Lumière sacrée (rang bas) pour les gros coups;Astuce : distribuer les bénédictions, Protection divine si vous prenez l'aggro"
T["Werte: +Heilung, Mana-Reg. (MP5), Intelligenz - Willenskraft bringt wenig;Waffe: Einhandwaffe + Schild mit Heilung;Heilen: Kettenheilung fuer Gruppen, Welle der Heilung (niedriger Rang) fuer den Tank;Tipp: Manaquelle-Totem stellen, Erdschild auf den Tank"] = "Stats : +soins, régén. mana (MP5), intelligence - l'esprit apporte peu;Arme : arme à une main + bouclier avec soins;Soins : Salve de guérison pour les groupes, Vague de soins (rang bas) pour le tank;Astuce : poser le Totem Fontaine de mana, Bouclier de terre sur le tank"
T["Werte: +Heilung, Willenskraft (Meditation: Regeneration auch beim Zaubern), Intelligenz, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung, Zauberstab;Heilen: Erneuerung und Machtwort: Schild vorab, Grosse Heilung (niedriger Rang) fuer den Tank;Tipp: Gebet der Heilung fuer die Gruppe, Verblassen bei Aggro"] = "Stats : +soins, esprit (Méditation : régén. même en incantant), intelligence, régén. mana;Arme : bâton ou arme à une main + main gauche avec soins, baguette;Soins : Rénovation et Mot de pouvoir : Bouclier en avance, Soins supérieurs (rang bas) pour le tank;Astuce : Prière de soins pour le groupe, Oubli en cas d'aggro"
T["Werte: Ruestung (Baerengestalt vervielfacht sie), Ausdauer, Beweglichkeit (Ausweichen + Ruestung);Waffe: egal fuer den Schaden - nur die Werte zaehlen (Stab/Stangenwaffe mit Ausdauer);Rotation: Zermalmen, Prankenhieb fuer Gruppen, Demoralisierendes Gebruell;Tipp: Staerke fuer mehr Bedrohung, Wutanfall zum Start"] = "Stats : armure (la forme d'ours la multiplie), endurance, agilité (esquive + armure);Arme : peu importe pour les dégâts - seules les stats comptent (bâton/arme d'hast avec endurance);Rotation : Mutilation, Balayage pour les groupes, Rugissement démoralisant;Astuce : force pour plus de menace, Enrager au début"
T["Werte: Staerke (1 Punkt = 2 AP), Beweglichkeit (AP + Krit), Krit, Treffer bis +9 %;Waffe: egal fuer den Schaden - nur die Werte zaehlen;Rotation: Krallenhieb/Schreddern fuer Combopunkte, dann Wilder Biss;Tipp: Machtwandel (Gestalt neu) fuer Energie, aus dem Schleichen anspringen"] = "Stats : force (1 point = 2 PA), agilité (PA + crit), crit, toucher jusqu'à +9 %;Arme : peu importe pour les dégâts - seules les stats comptent;Rotation : Griffe/Lambeau pour les points de combo, puis Morsure féroce;Astuce : changer de forme pour l'énergie, bondir depuis le rôdeur"
T["Werte: Staerke (1 Punkt = 2 AP), Krit (loest Schlaghagel aus = schneller schlagen), Treffer bis +9 %;Waffe: langsame Zweihandwaffe - Windzorn trifft pro Schlag, also je langsamer desto mehr Schaden;Rotation: Windzorn-Waffe, Sturmschlag, Erdschock;Tipp: Totem der Staerke der Erde und Windzorn-Totem fuer die Gruppe"] = "Stats : force (1 point = 2 PA), crit (déclenche Rafale = frappes plus rapides), toucher jusqu'à +9 %;Arme : arme à deux mains lente - Furie-des-vents frappe par coup, donc plus lente = plus de dégâts;Rotation : Arme Furie-des-vents, Frappe-tempête, Horion de terre;Astuce : Totem de Force de la Terre et Totem Furie-des-vents pour le groupe"
T["Werte: Staerke (1 Punkt = 2 AP), Krit, Treffer bis +9 %;Waffe: langsamer Zweihaender - Siegel und Richturteil wirken pro Schlag;Rotation: Siegel der Rechtschaffenheit/des Befehls, Richturteil, Siegel neu setzen;Tipp: Weihe nur mit genug Mana, Segen der Macht fuer dich"] = "Stats : force (1 point = 2 PA), crit, toucher jusqu'à +9 %;Arme : arme à deux mains lente - sceaux et Jugement agissent par coup;Rotation : Sceau de piété/d'autorité, Jugement, reposer le sceau;Astuce : Consécration seulement avec assez de mana, Bénédiction de puissance sur vous"
T["Werte: Treffer bis +9 %, Beweglichkeit (1 AP, ca. 29 = 1 % Krit), AP, Krit;Waffe: Kampf = schnelle Nebenhand, langsame Haupthand (Finsterer Stoss); Dolche fuer Meucheln;Rotation: Combopunkte aufbauen, Zerhaecksler oben halten, dann Ausweiden;Tipp: mit zwei Waffen verfehlen normale Schlaege oefter - Treffer ist am wichtigsten"] = "Stats : toucher jusqu'à +9 %, agilité (1 PA, env. 29 = 1 % crit), PA, crit;Arme : Combat = main gauche rapide, main droite lente (Attaque pernicieuse) ; dagues pour Embuscade;Rotation : accumuler des points de combo, maintenir Débiter, puis Éviscération;Astuce : avec deux armes, les coups normaux ratent plus souvent - le toucher est le plus important"
T["Werte: Treffer bis +9 %, Beweglichkeit (2 Distanz-AP, ca. 53 = 1 % Krit), AP, Intelligenz;Waffe: langsame Distanzwaffe (hoher Schaden pro Schuss), Nahkampfwaffe mit Werten;Rotation: Mal des Jaegers, Automatischer Schuss, Zielschuss/Mehrfachschuss dazwischen;Tipp: Begleiter fuettern und gluecklich halten, Eisfalle (Quadrat) als Kontrolle"] = "Stats : toucher jusqu'à +9 %, agilité (2 PA distance, env. 53 = 1 % crit), PA, intelligence;Arme : arme à distance lente (gros dégâts par tir), arme de mêlée avec stats;Rotation : Marque du chasseur, Tir automatique, Visée/Flèches multiples entre deux;Astuce : nourrir le familier et le garder heureux, Piège givrant (carré) pour le contrôle"
T["Werte: Treffer bis +9 %, Staerke (1 Punkt = 2 AP), Krit (ca. 20 Beweglichkeit = 1 %);Waffe: langsamer Zweihaender (Toedlicher Stoss, Heldenhafter Stoss wirken pro Schlag);Rotation: Wut aufbauen, Toedlicher Stoss / Blutdurst, Wirbelwind, ueberschuessige Wut in Heldenhaften Stoss;Tipp: Kampfrausch-Ruf vor dem Kampf, Hinrichten unter 20 % Leben"] = "Stats : toucher jusqu'à +9 %, force (1 point = 2 PA), crit (env. 20 agilité = 1 %);Arme : arme à deux mains lente (Frappe mortelle, Frappe héroïque agissent par coup);Rotation : générer de la rage, Frappe mortelle / Sanguinaire, Tourbillon, rage en trop dans Frappe héroïque;Astuce : Cri de guerre avant le combat, Exécution sous 20 % de vie"
T["Werte: Verteidigung (440 = auf 60 kritsicher gegen Bosse), Ausdauer, Ruestung, Schildblock;Waffe: Einhandwaffe + Schild, schnelle Waffe = mehr Wut;Rotation: Schildschlag/Rachsucht, Ruestung zerreissen auf das Ziel, Heldenhafter Stoss bei viel Wut;Tipp: Treffer hilft, damit Spott und Faehigkeiten nicht verfehlen"] = "Stats : défense (440 = immunité aux crits des boss au 60), endurance, armure, blocage;Arme : arme à une main + bouclier, arme rapide = plus de rage;Rotation : Heurt de bouclier/Vengeance, Fracasser armure sur la cible, Frappe héroïque avec beaucoup de rage;Astuce : le toucher aide pour que Provocation et les techniques ne ratent pas"
T["Werte: Verteidigung, Ausdauer, Ruestung, dann Zauberschaden fuer mehr Bedrohung;Waffe: Einhandwaffe (gern mit Zauberschaden) + Schild;Rotation: Zorn der Gerechtigkeit an, Weihe fuer Gruppen, Heiliger Schild oben halten;Tipp: Mana ist knapp - Siegel der Weisheit oder Intelligenz mitnehmen"] = "Stats : défense, endurance, armure, puis dégâts des sorts pour plus de menace;Arme : arme à une main (idéalement dégâts des sorts) + bouclier;Rotation : activer Fureur vertueuse, Consécration pour les groupes, maintenir Bouclier sacré;Astuce : le mana est juste - prendre Sceau de sagesse ou de l'intelligence"
T["Werte: Zauberschaden, Zauber-Krit (Elementarfokus spart Mana), Intelligenz, Mana-Reg.;Waffe: Einhandwaffe + Schild/Nebenhand mit Zauberschaden;Rotation: Blitzschlag spammen, Kettenblitz bei Gruppen, Flammenschock;Tipp: Zaubertreffer bis +16 % im Raid, Manaquelle-Totem gegen leeres Mana"] = "Stats : dégâts des sorts, critique des sorts (Focalisation élémentaire économise du mana), intelligence, régén. mana;Arme : arme à une main + bouclier/main gauche avec dégâts des sorts;Rotation : spammer Éclair, Chaîne d'éclairs en groupe, Horion de flammes;Astuce : toucher des sorts jusqu'à +16 % en raid, Totem Fontaine de mana contre le mana vide"
T["Werte: Zauberschaden, Zauber-Krit, Intelligenz, Zaubertreffer bis +16 % im Raid;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Mondfeuer + Insektenschwarm, dann Zorn oder Sternenfeuer;Tipp: Anregen fuer dich selbst, wenn das Mana knapp wird"] = "Stats : dégâts des sorts, critique des sorts, intelligence, toucher des sorts jusqu'à +16 % en raid;Arme : bâton ou arme à une main + main gauche avec dégâts des sorts;Rotation : Éclat lunaire + Essaim d'insectes, puis Colère ou Feu stellaire;Astuce : Innervation sur vous quand le mana devient juste"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Ausdauer, Intelligenz;Waffe: Stab oder Dolch + Nebenhand mit Zauberschaden, Zauberstab fuer Restmana;Rotation: Verderbnis + Fluch, dann Schattenblitz; Aderlass statt Trinken;Tipp: Ausdauer lohnt sich doppelt (Aderlass, Leerwandler/Seelenverbindung)"] = "Stats : dégâts des sorts, toucher des sorts jusqu'à +16 % (raid), endurance, intelligence;Arme : bâton ou dague + main gauche avec dégâts des sorts, baguette pour le mana restant;Rotation : Corruption + malédiction, puis Trait de l'ombre ; Connexion au lieu de boire;Astuce : l'endurance compte double (Connexion, Marcheur du Vide/Lien spirituel)"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Willenskraft fuer Mana;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Schattenwort: Schmerz, Gedankenschlag, Gedankenschinden;Tipp: Schattengestalt dauerhaft an, Vampirumarmung heilt die Gruppe"] = "Stats : dégâts des sorts, toucher des sorts jusqu'à +16 % (raid), esprit pour le mana;Arme : bâton ou arme à une main + main gauche avec dégâts des sorts;Rotation : Mot de l'ombre : Douleur, Attaque mentale, Fouet mental;Astuce : Forme d'ombre en permanence, Étreinte vampirique soigne le groupe"
T["Werte: Zauberschaden, dann Zaubertreffer bis +16 % (Raid-Bosse), Intelligenz, Zauber-Krit;Waffe: Stab mit Zauberschaden, dazu ein Zauberstab fuer Restmana;Rotation: Frostblitz bzw. Feuerball spammen, Hervorrufung bei leerem Mana;Leveln: Intelligenz und Willenskraft = weniger Pausen, in Gruppen Schaf (Mond) setzen"] = "Stats : dégâts des sorts, puis toucher des sorts jusqu'à +16 % (boss de raid), intelligence, critique des sorts;Arme : bâton avec dégâts des sorts, plus une baguette pour le mana restant;Rotation : spammer Éclair de givre ou Boule de feu, Évocation quand le mana est vide;Leveling : intelligence et esprit = moins de pauses, en groupe poser Métamorphose (lune)"
