T["Zeigt BESSER / SCHLECHTER / NICHT TRAGBAR mit Auswirkung (DPS, Leben, Ruestung) und Werte-Tabelle. Blizzards Vergleich erscheint dann nur mit Shift. Ist nesUI mit eigenem Vergleich geladen, zeigt Oasis nichts (sonst doppelt) - dort mit /nes vergleich abschalten."] = "Affiche MIEUX / MOINS BIEN / NON ÉQUIPABLE avec l'effet (DPS, vie, armure) et un tableau de stats. La comparaison Blizzard n'apparaît alors qu'avec Maj. Si nesUI est chargé avec sa propre comparaison, Oasis n'affiche rien (évite les doublons) - désactive-la avec /nes vergleich."
T["Zeigt Besser / Schlechter / Nicht tragbar mit Auswirkung (DPS, Leben, Ruestung) und Werte-Tabelle. Blizzards Vergleich erscheint dann nur mit Shift. Ist nesUI mit eigenem Vergleich geladen, zeigt Oasis nichts (sonst doppelt) - dort mit /nes vergleich abschalten."] = "Affiche Mieux / Moins bien / Non équipable avec l'effet (DPS, vie, armure) et un tableau de stats. La comparaison Blizzard n'apparaît alors qu'avec Maj. Si nesUI est chargé avec sa propre comparaison, Oasis n'affiche rien (évite les doublons) - désactive-la avec /nes vergleich."
T["Zeigt Beute aus Dungeons deines Levelbereichs, die besser ist als dein angelegtes Teil."] = "Affiche le butin de donjon de ta tranche de niveau meilleur que ta pièce équipée."
T["Zeigt ab Oasis-Rang 30 ein Juwel und ab Rang 70 einen schimmernden Namen im Oasis-Gildenchat"] = "Affiche un joyau dès le rang Oasis 30 et un nom scintillant dès le rang 70 dans le chat de guilde Oasis"
