T["Zeigt im Brachland ab und zu typische Sprueche im allgemeinen Chat - Chuck Norris, Mankriks Frau ... Nur bei dir, nichts wird gesendet."] = "Affiche de temps en temps des phrases typiques des Tarides dans le canal général - Chuck Norris, la femme de Mankrik ... Seulement pour toi, rien n'est envoyé."
