T["1.  Kampflog mitschreiben lassen (Einstellungen > Bereiche > Kampf-Rangliste, steht auf an).\n2.  Nach dem Spielen im Oasis-Ordner ImportCrits.bat doppelklicken.\n3.  Im Spiel /reload - dein hoechster Crit steht hier und wird mit der Gilde geteilt."] = "1.  Laisse le journal de combat actif (Options > Sections > Classement de combat, activé par défaut).\n2.  Après avoir joué, double-clique sur ImportCrits.bat dans le dossier Oasis.\n3.  /reload en jeu - ton plus gros critique s'affiche ici et est partagé avec la guilde."
T["1. Ueberschrift"] = "1. Titre"
T["2 Min"] = "2 min"
T["2. Nachricht"] = "2. Message"
T["3D-Modell"] = "Modèle 3D"
T["5 Min"] = "5 min"
T["Abend-Check"] = "Check du soir"
T["Aktionen"] = "Actions"
T["Aktiv: Meme-Sounds, Musik und Gilden-Emojis sind enthalten."] = "Actif : sons mèmes, musique et émojis de guilde inclus."
T["Aktive Mitglieder unterhalb der Offiziersraenge erscheinen nach so vielen Tagen im selben Rang in der Liste 'Befoerderung'. 0 = aus."] = "Les membres actifs sous les rangs d'officier apparaissent dans la liste « Promotion » après ce nombre de jours au même rang. 0 = désactivé."
T["Aktuelles Gebiet zuerst"] = "Zone actuelle d'abord"
T["Alle Bereiche, nach Themen gruppiert: Gilde, Zusammen spielen, Raid, Handel, Spass. Ein Klick auf eine Ueberschrift klappt die Gruppe zu."] = "Toutes les sections, par thème : guilde, jouer ensemble, raid, commerce, fun. Un clic sur un titre replie le groupe."
T["Alle Gebiete aufklappen"] = "Déplier toutes les zones"
T["Alle Gebiete zuklappen"] = "Replier toutes les zones"
T["Alle Mitglieder mit Rang, Stufe und Oasis-Version. Rechtsklick auf eine Zeile: Rang aendern."] = "Tous les membres avec rang, niveau et version d'Oasis. Clic droit sur une ligne : changer le rang."
T["Alle Schriften unter der SIL Open Font License 1.1"] = "Toutes les polices sous SIL Open Font License 1.1"
T["Alle: Brennendes Adrenalin: SOFORT aus dem Raid laufen (du stirbst gleich).\nAlle: Volle Ressourcen am Anfang - alles raushauen.\nTank: Tank-Reihenfolge festlegen (Adrenalin auf dem Tank).\nDD: Nicht vor oder hinter den Drachen."] = "All: Adrénaline brûlante : sors du raid TOUT DE SUITE (tu vas mourir).\nAll: Ressources pleines au début - lâchez tout.\nTank: Fixer un ordre des tanks (Adrénaline sur le tank).\nDD: Ni devant ni derrière le dragon."
T["Alle: Die 8 Feuerwichtel nicht in der Naehe des Raids sterben lassen (Explosion).\nTank: Jeder Wichtel-Tank zieht seinen Wichtel weg, Hexer verbannen.\nHeiler: Bannen, Wichtel-Tanks im Blick.\nDD: Garr zuerst, Wichtel nur gezielt."] = "All: Ne laissez pas les 8 Liges du feu mourir près du raid (explosion).\nTank: Chaque tank d'add éloigne son Lige du feu, les démonistes bannissent.\nHealer: Dissiper, surveiller les tanks d'adds.\nDD: Garr d'abord, les adds seulement sur appel."
T["Alle: Die beiden Kernhunde weg vom Boss tanken, nicht toeten.\nTank: Golemagg-Tank wechseln, wenn Magmasplitter zu hoch stapeln.\nDD: Nur auf Golemagg."] = "All: Tanker les deux Enragés du Magma loin du boss, ne pas les tuer.\nTank: Changer de tank sur Golemagg quand Eclaboussure de magma monte trop haut.\nDD: Uniquement sur Golemagg."
T["Alle: Erst die 4 Priester, sie heilen sich gegenseitig.\nTank: Herold und Priester getrennt.\nDD: Unterbrechen! Dunkle Besserung der Priester stoppen."] = "All: Les 4 prêtres d'abord, ils se soignent entre eux.\nTank: Séparer Sulfuron et les prêtres.\nDD: Interrompre ! Stopper Dark Mending des prêtres."
T["Alle: Feuerschutz! Wrath of Ragnaros wirft den Nahkampf weg - danach wieder ran.\nAlle: Phase der Soehne (nach 3 Min oder bei Untertauchen): alle Soehne der Flamme toeten.\nTank: Zweiter Tank bereit, wenn der erste weggeworfen wird.\nHeiler: Verteilt, Fernkampf nicht zu nah (Lavaplatscher).\nDD: Nahkampf: Mana unter Kontrolle, Fernkampf auf Abstand."] = "All: Protection contre le feu ! Colère de Ragnaros projette la mêlée - puis on y retourne.\nAll: Phase des Fils (après 3 min ou quand il s'enfonce) : tuer tous les Fils des flammes.\nTank: Second tank prêt quand le premier est projeté.\nHealer: Dispersés, distance pas trop près (Explosion de lave).\nDD: Mêlée : gérez votre mana, distance : restez à l'écart."
T["Alle: Flammenpuffer stapelt - Fernkampf hinter Saeulen zum Abbauen.\nTank: Zwei Tanks hinter Saeulen, Flugelschlag wirft zurueck.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Flame Buffet se cumule - distance derrière les piliers pour le faire tomber.\nTank: Deux tanks derrière les piliers, Frappe des ailes repousse.\nDD: Cape en écailles d'Onyxia obligatoire."
T["Alle: Fluch des Gehennas (weniger Heilung) sofort entfernen.\nAlle: Aus dem Feuerregen raus.\nTank: Die zwei Flammenwichtel getrennt tanken.\nDD: Wichtel zuerst, dann Gehennas."] = "All: Retirer la Malédiction de Gehennas (soins réduits) tout de suite.\nAll: Sortez de la Pluie de feu.\nTank: Tanker les deux Attise-flammes séparément.\nDD: Attise-flammes d'abord, puis Gehennas."
T["Alle: Fluch des Lucifron und Drohende Verdammnis sofort entfernen (Magier/Druiden, Priester/Paladine).\nTank: Die beiden Wachen getrennt tanken - Gedankenkontrolle!\nHeiler: Verteilt stehen, gedankenkontrollierte Spieler bannen.\nDD: Erst die Wachen, dann Lucifron."] = "All: Retirer tout de suite la Malédiction de Lucifron et Impending Doom (mages/druides, prêtres/paladins).\nTank: Tanker les deux gardes séparément - contrôle mental !\nHealer: Dispersés, dissiper les joueurs sous contrôle mental.\nDD: Les gardes d'abord, puis Lucifron."
T["Alle: Lebende Bombe: SOFORT raus aus dem Raid laufen!\nAlle: Inferno - weg vom Boss, Mana-Ausloeschung bannen.\nTank: Mitte halten, bei Inferno kurz raus.\nDD: Nahkampf bei Inferno zurueck."] = "All: Bombe vivante : sors du raid TOUT DE SUITE !\nAll: Inferno - loin du boss, dissiper Enflammer le mana.\nTank: Tenir le centre, sortir brièvement pendant Inferno.\nDD: La mêlée recule pendant Inferno."
T["Alle: Magiereflexion/Schadensschild der Wachen beachten - dann Schaden stoppen.\nTank: Jeder Tank eine Wache, Magier schafen die Elitewachen.\nDD: Heiler-Wachen (Flamewaker Healer) zuerst."] = "All: Attention au renvoi de magie/bouclier de dégâts des gardes - stoppez alors les dégâts.\nTank: Un garde par tank, les mages moutonnent les gardes d'élite.\nDD: Les gardes soigneurs (Soigneur attise-flammes) d'abord."
T["Alle: Nie vor oder hinter Onyxia stehen (Atem und Schwanzfeger).\nAlle: Phase 2 (65%): Feuerbaellen ausweichen, nicht in die Hoehlen-Eingaenge.\nAlle: Phase 3 (40%): Furcht - Furchtschutz/Erdungstotem bereit, Lava-Risse meiden.\nTank: Onyxia seitlich an der Wand, Kopf weg vom Raid.\nTank: Phase 2: Welpen einsammeln. Phase 3: Aggro sofort zurueck.\nHeiler: Tank hat Vorrang, in Phase 2 verteilt stehen.\nDD: 3 Angriffe des Tanks abwarten. Phase 2: Welpen zuerst."] = "All: Jamais devant ni derrière Onyxia (souffle et balayage de queue).\nAll: Phase 2 (65%): esquiver les boules de feu, pas dans les entrées des grottes.\nAll: Phase 3 (40%): peur - Gardien de peur/Totem de séisme prêts, éviter les fissures de lave.\nTank: Onyxia de côté contre le mur, tête loin du raid.\nTank: Phase 2 : ramasser les dragonnets. Phase 3 : reprendre l'aggro tout de suite.\nHealer: Priorité au tank, dispersés en phase 2.\nDD: Attendre 3 attaques du tank. Phase 2 : dragonnets d'abord."
T["Alle: Panik - Furchtschutz/Erdungstotem, Jaeger: Einlullender Schuss bei Raserei.\nAlle: Aus dem Lavafeuer am Boden raus.\nTank: Magmadar mit dem Ruecken zum Raid.\nDD: Fernkampf hinten verteilt."] = "All: Panique - Gardien de peur/Totem de séisme, chasseurs : Tir tranquillisant sur Frénésie.\nAll: Sortez du feu de lave au sol.\nTank: Magmadar dos au raid.\nDD: Distance dispersée à l'arrière."
T["Alle: Phase 1: Drachkin aus beiden Seiten, Klassenrufe beachten.\nAlle: Phase 3 (20%): Skelette wieder auferstanden - erneut toeten.\nTank: Nefarian an der Wand, Furcht - Furchtschutz.\nHeiler: Klassenruf fuer Priester: Heilung schadet - aufpassen.\nDD: Jaeger/Krieger: Klassenrufe beachten (Waffen weg, Haltung)."] = "All: Phase 1 : draconides des deux côtés, attention aux appels de classe.\nAll: Phase 3 (20%): les squelettes se relèvent - les tuer à nouveau.\nTank: Nefarian contre le mur, peur - Gardien de peur.\nHealer: Appel de classe prêtres : les soins blessent - attention.\nDD: Chasseurs/guerriers : attention aux appels de classe (armes perdues, posture)."
T["Alle: Phase 1: Eier zerstoeren (Gedankenkontrolle der Kugel), Adds abfangen.\nAlle: Nach allen Eiern: Boss im Raum - Feuerball-Nova.\nTank: Adds an den Treppen sammeln.\nDD: Magier und Drachkin zuerst."] = "All: Phase 1 : détruire les œufs (contrôle mental via l'orbe), récupérer les adds.\nAll: Après tous les œufs : boss dans la salle - Nova de feu.\nTank: Regrouper les adds aux escaliers.\nDD: Mages et draconides d'abord."
T["Alle: Raserei - Jaeger: Einlullender Schuss.\nTank: Zwei Tanks, Flugelschlag beachten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Frénésie - chasseurs : Tir tranquillisant.\nTank: Deux tanks, attention à Frappe des ailes.\nDD: Cape en écailles d'Onyxia obligatoire."
T["Alle: Schatten der Schattenschwinge heilt den Boss - Tank mit Debuff tauscht.\nTank: Zwei Tanks wechseln bei Schatten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Ombre de Rochébène soigne le boss - le tank avec le débuff échange.\nTank: Deux tanks échangent sur Ombre.\nDD: Cape en écailles d'Onyxia obligatoire."
T["Alle: Stoss zurueck - an die Wand stellen.\nTank: Zwei Tanks, Aggro wird durch Niederschlagen geteilt.\nDD: Mortalschlag auf Tank: Heiler vorbereiten."] = "All: Projection - collez-vous au mur.\nTank: Deux tanks, l'aggro est partagée par Repousser au loin.\nDD: Frappe mortelle sur le tank : soigneurs, soyez prêts."
T["Alle: Teleportiert sich - wer Aggro hat, nicht wegrennen.\nAlle: Fluch des Shazzrah entfernen, Arkane Explosion: Nahkampf auf Abstand.\nTank: Nach jedem Blinzeln sofort wieder ran.\nHeiler: Bannen (Deaktivieren-Magie)."] = "All: Il se téléporte - celui qui a l'aggro ne s'enfuit pas.\nAll: Retirer la Malédiction de Shazzrah, Explosion des arcanes : mêlée à distance.\nTank: Retourner sur lui juste après chaque transfert.\nHealer: Dissiper (Atténuation de la magie)."
T["Alle: Zwei der fuenf Atem-Arten je Woche - Atem verlaesst man hinter der Ecke.\nAlle: Hourglass Sand fuer Bronze-Affliktion.\nTank: Am Tor tanken, Raid hinter der Ecke.\nDD: Bei Raserei Einlullender Schuss."] = "All: Deux des cinq types de souffle par semaine - éviter le souffle derrière l'angle.\nAll: Sable du sablier pour l'affliction de bronze.\nTank: Tanker à la porte, raid derrière l'angle.\nDD: Tir tranquillisant sur Frénésie."
T["Alt halten: alle Werte und Bewertung. Shift: Blizzard-Vergleich."] = "Maintenir Alt : toutes les stats et le détail du score. Maj : comparaison Blizzard."
T["Alt loslassen: kompakter Vergleich. Shift: Blizzard-Vergleich."] = "Relâcher Alt : vue compacte. Maj : comparaison Blizzard."
