T["Banner auf der Uebersicht: Midas, das Auktionshaus-Addon von Rebo aus der Gilde OASIS"] = "Bannière sur l'aperçu : Midas, l'addon d'hôtel des ventes de Rebo, de la guilde OASIS"
T["Befoerderung vorschlagen nach"] = "Proposer une promotion après"
T["Beim naechsten Wurf siehst du alt aus!"] = "Au prochain lancer, t'es cuit !"
T["Beispieldaten gibt es nur in der Entwicklerversion."] = "Les données d'exemple n'existent que dans la version développeur."
T["Bereiche freigeben"] = "Activer des sections"
T["Bereit fuer den Pull? Bereitschaft, Verzauberungen und Buffs je Spieler"] = "Prêts pour le pull ? Disponibilité, enchantements et buffs par joueur"
T["Bestaetigte Crit-Rekorde aus der Logdatei importiert."] = "Records de critiques confirmés importés du fichier journal."
