T["Boss der Defias"] = "Chef des Défias"
T["Boss von Ratschet - alles hat seinen Preis"] = "Patron de Cabestan - tout a un prix"
T["Boss-Positionen im Dungeon-Atlas und Drop-Chancen der Dungeon-Bosse - GPL-2.0. Autoren: Lag, Daviesh und weitere"] = "Positions des boss dans l'atlas des donjons et taux de butin des boss de donjon – GPL-2.0. Auteurs : Lag, Daviesh et d'autres"
