T["Charakterstatistik - hoechster Einzelwert, Crit-Status unbekannt"] = "Statistique du personnage – plus haute valeur unique, statut critique inconnu"
T["Chat-Eingabe und Zauberbefehle koennen beteiligt sein."] = "La saisie dans le chat et les commandes de sort peuvent être en cause."
T["Chat-Eingabe und Zielwechsel koennen beteiligt sein."] = "La saisie dans le chat et les changements de cible peuvent être en cause."
T["Chatnachrichten erfordern in diesem Client eine direkte Eingabe."] = "Dans ce client, les messages de chat exigent une saisie directe."
T["Credits"] = "Crédits"
T["Crit-Heilung"] = "Soin critique"
T["Crit-Import gehoert zu einem anderen Charakter."] = "L'import de critiques appartient à un autre personnage."
T["Crit-Quelle pruefen"] = "Vérifier la source des critiques"
T["Crit-Rekorde aus den Kampflog-Dateien uebernommen."] = "Records de critiques importés des fichiers du journal de combat."
T["Crits beim Kampf allein automatisch zaehlen"] = "Compter les critiques automatiquement en combat solo"
T["Crits in Gruppe und Dungeon schaetzen"] = "Estimer les critiques en groupe et en donjon"
T["Das X am Fenster klappt Oasis in die Leiste ein. Das X an der Leiste schliesst ganz."] = "Le X de la fenêtre replie Oasis dans la barre. Le X de la barre ferme tout."
T["Das gelbe Ausrufezeichen am Symbol zeigt das an."] = "Le point d'exclamation jaune sur l'icône le signale."
T["Das war nur Glueck! Nochmal!"] = "C'était juste de la chance ! Encore !"
T["Das war's schon. Den Rundgang findest du jederzeit wieder unter Einstellungen > Status oder mit /oa rundgang."] = "C'est déjà fini. Tu retrouves la visite à tout moment dans Options > Statut ou avec /oa rundgang."
T["Daten"] = "Données"
T["Deckend"] = "Opaque"
T["Dein Charakter"] = "Ton personnage"
T["Deine Stats: Oasis-Rang, Abzeichen und alle Zaehler"] = "Tes stats : rang Oasis, badges et tous les compteurs"
T["Den Download findest du im Discord der Gilde."] = "Le téléchargement se trouve sur le Discord de la guilde."
T["Der Client erlaubt Oasis nicht, das Kampflog einzuschalten - bitte selbst /combatlog eingeben."] = "Le client n'autorise pas Oasis à activer le journal de combat - tape /combatlog toi-même."
T["Der Inhalt des gewaehlten Bereichs. Die Uebersicht zeigt, wer online ist, was ansteht und was es Neues gibt."] = "Le contenu de la section choisie. L'aperçu montre qui est en ligne, ce qui arrive et les nouveautés."
T["Der Minimap-Knopf oder /oa oeffnet Oasis. Mit dem Strich oben rechts wird das Fenster zu einer schmalen Leiste."] = "Le bouton de la minicarte ou /oa ouvre Oasis. Le trait en haut à droite réduit la fenêtre en une barre étroite."
T["Der Offizierskanal (/o) mit Verlauf - nur fuer Raenge mit Offizierschat-Recht."] = "Le canal des officiers (/o) avec historique - réservé aux rangs ayant le droit de chat des officiers."
T["Der gelbe Strich links in der Liste zeigt das an."] = "Le trait jaune à gauche dans la liste le signale."
T["Details schliessen"] = "Fermer les détails"
T["Deutlicher Standard-Ton bei Online-Meldungen"] = "Son par défaut plus net pour les avis de connexion"
T["Die Charakterstatistik ist in diesem Client nicht verfuegbar."] = "Les statistiques du personnage ne sont pas disponibles dans ce client."
T["Die Gildenleitung hat Soundeffekte fuer dich gesperrt."] = "La direction de la guilde a bloqué les effets sonores pour toi."
T["Die Leiste ist ab dem Einloggen da und bleibt - das X am Fenster schliesst nur das Fenster."] = "La barre est là dès la connexion et reste - le X de la fenêtre ne ferme que la fenêtre."
T["Die Prozentzahl vergleicht die Item-Wertung fuer deine Rolle, nicht deinen gesamten Schaden. Auswirkungen sind Schaetzwerte."] = "Le pourcentage compare le score de l'objet pour ton rôle, pas tes dégâts totaux. Les effets sont des estimations."
T["Die Statistik liefert derzeit keinen lesbaren Wert."] = "La statistique ne fournit actuellement aucune valeur lisible."
T["Die Zentrale eurer Gilde. In 30 Sekunden kennst du dich aus - hier ist das Wichtigste."] = "Le centre de votre guilde. En 30 secondes tu t'y retrouves - voici l'essentiel."
T["Die geschuetzte Funktion wurde blockiert. Der genaue Ausloeser ist noch unbekannt."] = "La fonction protégée a été bloquée. La cause exacte est encore inconnue."
T["Die passende Charakterstatistik wurde noch nicht gefunden."] = "La statistique de personnage correspondante n'a pas encore été trouvée."
