T["Was die Leitung geaendert hat, Auffaelligkeiten, Daten sichern."] = "Ce que la direction a modifié, anomalies, sauvegarde des données."
T["Was du fuer den naechsten Raid noch brauchst - Widerstaende, Verbrauchsgueter, Haltbarkeit, Schluessel"] = "Ce qu'il te manque pour le prochain raid - résistances, consommables, durabilité, clés"
