T["Wer an einem Abend schon ein Item mit Bedarf bekommen hat, rutscht bei Bedarf hinter alle ohne Item (gleicher Wurf-Rang)."] = "Qui a déjà reçu un objet en Besoin ce soir-là passe, en Besoin, derrière tous ceux sans objet (même rang de lancer)."
T["Wer ein Item fuer den Termin reserviert hat, kommt bei Bedarf vor allen anderen."] = "Qui a réservé un objet pour l'événement passe avant tous les autres en Besoin."
T["Wer in Gruppe oder Raid welche Buffs hat - und wer das Fehlende geben kann"] = "Qui a quels buffs dans le groupe ou le raid - et qui peut donner ce qui manque"
T["Wer ist in der Gilde, welcher Rang, wer hat altes Oasis."] = "Qui est dans la guilde, quel rang, qui a un ancien Oasis."
T["Wer war lange nicht online - aufraeumen mit einem Klick."] = "Qui n'est plus venu depuis longtemps - nettoyage en un clic."
T["Wie die Schrift"] = "Comme la police"
T["Wieder am Talentfenster andocken"] = "Réancrer à la fenêtre des talents"
T["WoW sagt Addons in der Gruppe nicht, wer getroffen hat. Oasis zaehlt einen kritischen Treffer nur, wenn er direkt auf deinen eigenen Angriff folgt und nach dem Kampf zur Schadensanzeige passt. In der Rangliste als geschaetzt markiert."] = "En groupe, WoW n'indique pas aux addons qui a touché. Oasis ne compte un coup critique que s'il suit directement ta propre attaque et correspond au compteur de dégâts après le combat. Marqué comme estimé dans le classement."
T["WoW-Klassiker"] = "Classiques de WoW"
T["Wochenaufgaben %d/%d"] = "Tâches de la semaine %d/%d"
T["World of Warcraft und zugehoerige Namen, Wappen und Grafiken sind Marken von Blizzard Entertainment. Oasis ist ein Fan-Projekt und steht in keiner Verbindung zu Blizzard."] = "World of Warcraft et les noms, blasons et illustrations associés sont des marques de Blizzard Entertainment. Oasis est un projet de fans sans lien avec Blizzard."
T["Wuerfeln: Reihenfolge Bedarf > Zweitspec > Transmog, dann Wurf. Punkte: Prioritaet aus den Beutepunkten entscheidet. Beuterat: Offiziere stimmen ab, der Plundermeister vergibt."] = "Dés : ordre besoin > double spé > transmo, puis le lancer. Points : la priorité des points de butin décide. Conseil du butin : les officiers votent, le maître du butin attribue."
T["Zahnrad = Einstellungen (Aussehen, Toene, Hinweise). Daneben Sprache und - fuer die Gildenleitung - die Krone."] = "Engrenage = options (apparence, sons, notifications). À côté, la langue et - pour la direction de la guilde - la couronne."
T["Zeigt bei gruenen, blauen und epischen Teilen, welche Materialien beim Entzaubern herauskommen koennen"] = "Indique quels matériaux peuvent sortir du désenchantement des objets verts, bleus et épiques"
T["Zeigt in der Suche an, dass ihr per Sprache redet (Discord o.ae.). Beitreten regelt weiter Blizzard bzw. dein Gruppenleiter."] = "Indique dans la recherche que vous parlez en vocal (Discord, etc.). Rejoindre reste géré par Blizzard ou ton chef de groupe."
