T["Im Kampf oeffnet Oasis die Karte nicht - das Ziel ist gesetzt, oeffne die Karte nach dem Kampf."] = "Oasis n'ouvre pas la carte en combat - la destination est définie, ouvrez la carte après le combat."
T["Noch nicht gelernt - diese Waffen- oder Ruestungsart kannst du noch nicht anlegen"] = "Pas encore appris - vous ne pouvez pas encore équiper ce type d'arme ou d'armure"
T["Beispieldaten"] = "Données d'exemple"
