T["Klick: oeffnen"] = "Clic : ouvrir"
T["Kritische Treffer beim Solo-Spiel zaehlen automatisch. In Gruppe und Dungeon schaetzt Oasis sie und markiert sie so."] = "Les coups critiques en solo sont comptés automatiquement. En groupe et en donjon, Oasis les estime et les marque comme tels."
T["Neuigkeiten"] = "Nouveautés"
T["Scan fertig: %d Pruefungen, %d Fehler. Jetzt /reload, dann ist das Ergebnis gespeichert."] = "Scan terminé : %d vérifications, %d erreurs. Faites /reload pour enregistrer le résultat."
T["So sieht Oasis mit einer Gilde aus: Beispieldaten nur auf deinem PC, es wird nichts gesendet. Entfernen mit /oa demo aus."] = "Voici Oasis avec une guilde : données d'exemple uniquement sur votre PC, rien n'est envoyé. Supprimer avec /oa demo off."
T["Solange sie laufen, steht oben im Fenster 'Demo an'. Ein Klick dort oder hier entfernt alles wieder."] = "Tant qu'elles sont actives, la fenêtre affiche « Démo activée » en haut. Un clic là ou ici supprime tout."
T["Treffpunkt, Vorsicht oder Notiz: Art waehlen, dann auf die Karte klicken"] = "Point de rendez-vous, danger ou note : choisissez un type, puis cliquez sur la carte"
